30	  // travels with every call: a caller working in one checkout may be applying the
31	  // labels to another repository, and a label created in the wrong one makes the
32	  // `issue edit` fail as "label not found" (the #223 review's third point).
33	  const create = (label: string, color: string, description: string) =>
34	    gh("label", "create", label, "--force", "-c", color, "-d", description, ...(repo ? ["--repo", repo] : []));
35	
36	  if (phase === "running") {
37	    create(inProgress, "0366d6", "Issue is being worked on by an Atomaton agent");
38	    const added = edit("--add-label", inProgress);
39	    if (added.code !== 0) console.error(`::warning::could not add '${inProgress}' to #${number}`);
40	    const removed = edit("--remove-label", waitingForPerson);
41	    if (removed.code !== 0) console.error(`::warning::could not remove '${waitingForPerson}' from #${number}`);
42	    return;
43	  }
44	
45	  create(waitingForPerson, "fbca04", "The turn is with a person on this issue or pull request");
46	  const removed = edit("--remove-label", inProgress);
